"""F1 trace-level predictor. For traces generated by edit theta0 (TF'd through base), predicts proxy acc/trunc under edit theta.
Weights: each (bench, outcome) cell reweighted to the full proxy population of the generating run.
Per trace: P(close at t) = pi_t * S_t over observed positions; label premature (t < A: reference answer not yet in text) -> a0;
legit (t >= A): closed traces -> own correctness; truncated traces -> a_L.  Remaining mass S_end:
closed traces -> would close later (finished state): closed with own correctness w.p. (1-eps), truncated w.p. eps;
truncated traces -> stays truncated (stuck state), unless lam_stuck > 0.
usage: python predict.py TFDIR RESNAME"""
import sys, json, numpy as np; sys.path.insert(0, '/home/user/delta/agents/f1')
from sampler import *
import hazard
def load(tfdir, res_name):
    tr = load_dir(tfdir)
    texts = {json.loads(l)['id']: json.loads(l)['text'] for l in open(f'/home/user/delta/agents/f1/results/{res_name}.texts.jsonl')}
    rows = {r['id']: r for r in json.load(open(f'/home/user/delta/agents/f1/results/{res_name}.json'))['rows']}
    hazard.texts_score = {i: r['score'] for i, r in rows.items()}
    cell = lambda r: (r['bench'], 'trunc' if r['truncated'] else ('ok' if r['score'] > 0 else 'wrong'))
    pop = {}; 
    for r in rows.values(): pop[cell(r)] = pop.get(cell(r), 0) + 1
    samp = {}
    for k in tr: c = cell(rows[int(k.split('_')[0])]); samp[c] = samp.get(c, 0) + 1
    W = {k: pop[cell(rows[int(k.split('_')[0])])] / samp[cell(rows[int(k.split('_')[0])])] / len(rows) for k in tr}
    return tr, texts, rows, W
def predict(tr, texts, W, th, a0=0.31, a_L=0.7, G_fin=100.0, lam_stuck=0.0):
    """finished-state closing: the S_end mass of a closed trace keeps meeting 'finished gateways' every G_fin tokens, each
    closing w.p. p_fin(theta) = weighted mean of pi_theta at the actual close positions (the empirical finished gateways)."""
    res = hazard.analyze(tr, texts, th)
    Wn = sum(W.values())
    cl = [r for r in res if r['closed']]
    p_fin = sum(W[f"{r['id']}_0"] * r['pi_last'] for r in cl) / max(1e-9, sum(W[f"{r['id']}_0"] for r in cl))
    sc = tr_ = 0.0
    for r in res:
        w = W[f"{r['id']}_0"] / Wn; rem = max(0.0, 8192 - r['n'])
        if r['closed']:
            P_later = 1 - (1 - p_fin) ** (rem / G_fin)
            s = r['p_prem'] * a0 + r['p_legit'] * r['correct'] + r['S_end'] * P_later * r['correct']; t_ = r['S_end'] * (1 - P_later)
        else:
            s = r['p_prem'] * a0 + r['p_legit'] * a_L; t_ = r['S_end']
        sc += w * s; tr_ += w * t_
    return 100 * sc, tr_, res
if __name__ == '__main__':
    tr, texts, rows, W = load(sys.argv[1], sys.argv[2])
    print(len(tr), 'traces; weights sum', round(sum(W.values()), 3))
    S = [dict(NEWLEADER, c=c) for c in [1.0, 1.15, 1.2, 1.25, 1.3, 1.35, 1.4, 1.45, 1.5]]
    names = [f'stack c={th["c"]}' for th in S]
    S += [dict(NEWLEADER, g=g) for g in [1.3, 1.55]]; names += ['stack g=1.3', 'stack g=1.55']
    S += [dict(NEWLEADER, s={k: 0.5 for k in H13}), dict(c=1.5), dict(c=1.3), dict(g=1.4, c=1.3), BASE, LEADER1, dict(g=1.667)]
    names += ['stack h13', 'c1.5 alone', 'c1.3 alone', 'g1.4+c1.3 (no dampen)', 'base', 'leader1', 'g1.667']
    a0s = [float(x) for x in (sys.argv[3].split(',') if len(sys.argv) > 3 else ['0.31', '0.05'])]
    print('a0 (premature-close accuracy) values:', a0s, ' a_L=0.7 (late legit close in a stuck trace), G_fin=100')
    for name, th in zip(names, S):
        outs = [predict(tr, texts, W, th, a0=a0) for a0 in a0s]
        print(f'{name:24s} ' + '  '.join(f'[a0={a0}] acc {acc:5.1f} trunc {trunc:.3f}' for a0, (acc, trunc, _) in zip(a0s, outs)))
